    await writeAudit('æ›´æ–°å•†å“å¹³å°ä¸Šæž¶ç‹€æ…‹','product',id,(p.sku||id)+'ï½œ'+PRODUCT_LISTING_PLATFORMS.map(function(platform){return platform.label+':'+(PRODUCT_PLATFORM_STATUS_META[statuses[platform.key].status]||PRODUCT_PLATFORM_STATUS_META.unknown).label;}).join('ã€'));
