  async function startProductListingQueue(){
    let rows=productListingQueueRows().filter(function(row){return row.batchQueueStatus!=='processing';});if(!rows.length)throw new Error('ç›®å‰æ²’æœ‰ç­‰å¾…è™•ç†çš„å•†å“');
    if(rows.length>50)throw new Error('ä¸€æ¬¡æœ€å¤šè™•ç† 50 ä»¶ï¼Œè«‹å…ˆç§»é™¤é€™æ¬¡ä¸è™•ç†çš„å•†å“');
    await requireEasyStoreManagerAuth();
    const runId='listing-batch-'+Date.now().toString(36),batch=state.db.batch(),serverTime=serverTimestamp();
    rows.forEach(function(row,index){batch.set(state.db.collection(COLLECTIONS.listingCases).doc(row.productId),{batchQueueStatus:'processing',batchRunId:runId,batchPosition:index+1,batchQueueError:'',batchQueueUpdatedAt:serverTime,caseStatus:'waiting-codex',updatedAt:serverTime,updatedBy:userLabel(),version:VERSION},{merge:true});});
    await batch.commit();
    rows=rows.map(function(row,index){return Object.assign({},row,{batchQueueStatus:'processing',batchRunId:runId,batchPosition:index+1,batchQueueUpdatedAt:new Date()});});rows.forEach(upsertProductListingQueueState);
    const prompt=productListingBatchActivationPrompt(rows,runId),threadUrl=productListingCodexThreadUrl(prompt),copied=await copyProductListingCodexPrompt(prompt),status=byId('productListingQueueStatus');
    if(status)status.innerHTML='<div class="ops-product-ai-status completed"><span>âœ“</span><div><b>å·²å¸¶å…¥ '+rows.length+' ä»¶å•†å“</b><small>Codex æœƒç…§æ¸…å–®é †åºé€ä»¶è™•ç†'+(copied?'ï¼›æ‰¹æ¬¡æ–‡å­—ä¹Ÿå·²è¤‡è£½':'')+'ã€‚</small></div></div>';
    await writeAudit('æ‰¹æ¬¡äº¤çµ¦ Codex å°è©±è™•ç†','productListingBatch',runId,rows.map(function(row){return row.productSku||row.productId;}).join('ã€'));
    global.setTimeout(function(){global.location.href=threadUrl;},100);
  }

